def count_kawaii(n, m):
    # Counts partitions of {1, ..., n} into m non-empty sets P_1, ..., P_m
    # such that min(P_1) < max(P_2), min(P_2) < max(P_3), ..., min(P_{m-1}) < max(P_m)
    import itertools
    count = 0
    # Generate all partitions of {1, ..., n} into m non-empty sets
    # This is not efficient for large n, but we only need small n
    for p in itertools.product(range(m), repeat=n):
        # p[i] is the set index for position i+1
        # Check if all set indices 0...m-1 are present
        if len(set(p)) == m:
            sets = [[] for _ in range(m)]
            for i, set_idx in enumerate(p):
                sets[set_idx].append(i + 1)

            # Condition: min(P_1) < max(P_2), min(P_2) < max(P_3), ..., min(P_{m-1}) < max(P_m)
            # Note: set indices are 0...m-1. So min(P_0) < max(P_1), ..., min(P_{m-2}) < max(P_{m-1})
            possible = True
            for k in range(m - 1):
                if not (min(sets[k]) < max(sets[k+1])):
                    possible = False
                    break
            if possible:
                count += 1
    return count

