def count_kawaii(n):
    import itertools
    count = 0
    # Elements can be from 1 to n. But the set of elements must be {1, ..., m}
    # for some m <= n.
    for m in range(1, n + 1):
        # Elements from {1, ..., m}
        for seq in itertools.product(range(1, m + 1), repeat=n):
            if set(seq) == set(range(1, m + 1)):
                if is_kawaii(seq):
                    count += 1
    return count

