def count_small_m(n, m):
    import itertools
    count = 0
    for seq in itertools.product(range(1, m + 1), repeat=n):
        if set(seq) != set(range(1, m + 1)):
            continue
        is_kawaii = True
        for k in range(2, m + 1):
            first_k_minus_1 = seq.index(k-1)
            last_k = max(i for i, x in enumerate(seq) if x == k)
            if first_k_minus_1 >= last_k:
                is_kawaii = False
                break
        if is_kawaii:
            count += 1
    return count

for n in range(1, 6):
